    for (let i = 0; i < 15; i++) setFunc(tl[i][0], tl[i][1], fBit(i));
    for (let i = 0; i < 8; i++) setFunc(8, N - 1 - i, fBit(i));
    for (let i = 8; i < 15; i++) setFunc(N - 15 + i, 8, fBit(i));

